edits.newText:
Widget buildHeroGestureSurface({required Widget child}) {
  final player = context.read<PlaybackController>();
  final acceptVertical =
      browserPresentation.value == BrowserPresentation.swipeUp &&
      !browserExpanded.value;
  return HeroFeedbackSurface(
    flashController: heroFlashController,
    onPlayPause: () => player.playPause(),
    onPrevious: () => player.previous(),
    onNext: () => player.next(),
    onSeek: (d) => player.seek(d),
    positionMs: () => player.songInfo?.position ?? 0,
    durationMs: () => player.songInfo?.duration ?? 0,
    // Linux: hide the built-in seek HUD overlay and instead print the
    // seek target/duration/progress in the bottom folder (crumb) line.
    showSeekHud: !showSeekPreviewInCrumb,
    onSeekPreview: showSeekPreviewInCrumb
        ? (target, duration, fraction) {
            seekPreview.value = (
              targetMs: target.inMilliseconds,
              durationMs: duration.inMilliseconds,
              fraction: fraction,
            );
          }
        : null,
    onSeekPreviewEnd: showSeekPreviewInCrumb
        ? () => seekPreview.value = null
        : null,
    onVerticalDragUpdate: acceptVertical ? onHeroVerticalDrag : null,
    onVerticalDragEnd: acceptVertical ? onHeroVerticalDragEnd : null,
    child: child,
  );
}

